const trigger = $('When Executed by Another Workflow').item.json;
const post = trigger.post_final || '';
const hashtags = trigger.hashtags || '';

const systemPrompt = `Você é um analista de compliance regulatório especializado nas normas da CVM (Comissão de Valores Mobiliários) para assessores de investimento registrados no Brasil, com base na Resolução CVM nº 178/2023 (arts. 23 e 24) e nas regras de publicidade da CVM.

O autor é assessor de investimentos de um escritório parceiro de uma corretora (intermediário). Posts que mencionam produtos/serviços específicos costumam fechar com "Na [Escritório] | [Corretora] temos a solução certa para você" — isso identifica o intermediário conforme exige o Art. 24 da Resolução CVM 178.

Responda SOMENTE com um JSON no formato:
{"compliance_status": "aprovado" ou "bloqueado", "motivo": "explicação curta", "trechos_problematicos": ["trecho 1", "trecho 2"]}

BLOQUEIE o post se contiver qualquer um destes pontos:
1. Promessa ou garantia de rentabilidade/retorno futuro. (Termos hedged como "pode", "possível", "potencial", "projetado" são aceitáveis; afirmações categóricas como "vai render", "retorno garantido", "certeza de lucro" não são.)
2. Menção a rentabilidade passada de um ativo/produto sem disclaimer (que rentabilidade passada não garante retorno futuro).
3. Recomendação ou menção a um produto/serviço financeiro específico (nome de fundo, ação, plano de previdência, etc) SEM a identificação do intermediário [Escritório] | [Corretora] em algum ponto do texto (Art. 24 da Resolução CVM 178 exige essa identificação nesses casos).
4. Comparação de performance com concorrentes sem base auditável/comprovável.
5. Conflito de interesse não declarado (ex: promoção de produto próprio ou de terceiro sem transparência).
6. Tom sensacionalista, alarmista ou de urgência artificial (a CVM exige linguagem calma e moderada em comunicação pública).

APROVE o post se for conteúdo educacional/opinativo neutro: comentário sobre notícia, cenário macro, comportamento humano, gestão de risco ou tomada de decisão, SEM recomendar produto específico e SEM prometer retorno. Esse é o formato padrão usado por este assessor e está dentro do permitido — não seja excessivamente restritivo com esse tipo de conteúdo.`;

const userPrompt = `Texto do post:\n\n${post}\n\nHashtags: ${hashtags}`;

return {
  json: {
    requestBody: {
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0.1
    }
  }
};

const raw = $json.choices[0].message.content;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    compliance_status: 'bloqueado',
    motivo: 'Erro ao interpretar resposta da IA: ' + e.message,
    trechos_problematicos: []
  };
}

return {
  json: {
    compliance_status: parsed.compliance_status,
    compliance_motivo: parsed.motivo,
    compliance_trechos: (parsed.trechos_problematicos || []).join(' | ')
  }
};

const trigger = $('When Executed by Another Workflow').item.json;
const post = trigger.post_final || '';
const resumoFatos = trigger.resumo || '';

const systemPrompt = `Você é um fact-checker seguindo os padrões do IFCN (International Fact-Checking Network) e da metodologia de agências como a Agência Lupa: verifica APENAS afirmações factuais verificáveis (eventos, datas, números, nomes, o que efetivamente aconteceu) — NUNCA checa opiniões, reflexões ou interpretações pessoais do autor.

Você vai comparar um post do LinkedIn com o resumo de fatos apurados que serviu de base para escrevê-lo.

Responda SOMENTE com um JSON no formato:
{"fact_check_status": "ok" ou "divergencia", "motivo": "explicação curta", "afirmacoes_nao_verificadas": ["afirmação 1", "afirmação 2"]}

Processo:
1. Identifique no post SOMENTE as afirmações factuais sobre o evento noticiado (o que aconteceu, quando, com quem, números, datas, nomes). Ignore completamente frases de opinião, reflexão sobre risco/comportamento/decisão — essas não são checáveis e não devem aparecer em "afirmacoes_nao_verificadas".
2. Para cada afirmação factual identificada, verifique se ela é sustentada pelo resumo de fatos apurados abaixo.
3. Se todas as afirmações factuais forem sustentadas (ou se o post não contiver nenhuma afirmação factual verificável, só opinião), retorne "ok".
4. Se alguma afirmação factual contradisser o resumo ou não tiver base nele (possível invenção/alucinação da IA em etapas anteriores), retorne "divergencia" e liste as afirmações problemáticas.`;

const userPrompt = `RESUMO DE FATOS APURADOS (fonte de verdade):\n${resumoFatos}\n\nPOST A VERIFICAR:\n${post}`;

return {
  json: {
    requestBody: {
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0.1
    }
  }
};

const raw = $json.choices[0].message.content;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    fact_check_status: 'divergencia',
    motivo: 'Erro ao interpretar resposta da IA: ' + e.message,
    afirmacoes_nao_verificadas: []
  };
}

return {
  json: {
    fact_check_status: parsed.fact_check_status,
    fact_check_motivo: parsed.motivo,
    fact_check_afirmacoes: (parsed.afirmacoes_nao_verificadas || []).join(' | ')
  }
};

const trigger = $('When Executed by Another Workflow').item.json;
const complianceResult = $('09. Compliance CVM - Parse Resposta').item.json;
const factCheckResult = $('08. Fact-checker - Parse Resposta').item.json;

const post = trigger.post_final || '';
const articles = trigger.articles || [];
const sourceText = articles.map(a => a.text || '').join(' ');

function normalize(text) {
  return text
    .toLowerCase()
    .replace(/[^\wà-ú\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ');
}

function getShingles(words, k) {
  const shingles = new Set();
  for (let i = 0; i <= words.length - k; i++) {
    shingles.add(words.slice(i, i + k).join(' '));
  }
  return shingles;
}

function jaccardSimilarity(setA, setB) {
  if (setA.size === 0 || setB.size === 0) return 0;
  let intersection = 0;
  for (const shingle of setA) {
    if (setB.has(shingle)) intersection++;
  }
  const union = setA.size + setB.size - intersection;
  return union === 0 ? 0 : intersection / union;
}

const K = 5;
const postShingles = getShingles(normalize(post), K);
const sourceShingles = getShingles(normalize(sourceText), K);
const similarity = jaccardSimilarity(postShingles, sourceShingles);
const originalidadeScore = Math.round((1 - similarity) * 100);

const LIMIAR_BAIXA_ORIGINALIDADE = 70;
const originalidadeAlerta = originalidadeScore < LIMIAR_BAIXA_ORIGINALIDADE;

return {
  json: {
    topic: trigger.topic,
    post_final: trigger.post_final,
    hashtags: trigger.hashtags,
    checklist: trigger.checklist,
    ajustes_feitos: trigger.ajustes_feitos,
    cta_tipo: trigger.cta_tipo,
    compliance_status: complianceResult.compliance_status,
    compliance_motivo: complianceResult.compliance_motivo,
    fact_check_status: factCheckResult.fact_check_status,
    fact_check_motivo: factCheckResult.fact_check_motivo,
    originalidade_score: originalidadeScore,
    originalidade_alerta: originalidadeAlerta
  }
};
